#!/bin/bash
set -e

echo "=========================================================="
echo "  MAESTRO STUDIO: PUSH SORGENTI & BUILD APK AUTOMATICO    "
echo "  Target Repo: msarti81-design / maestro-studio           "
echo "=========================================================="

if [ -d "/var/www/maestro-studio" ]; then
    APP_DIR="/var/www/maestro-studio"
elif [ -d "/root/maestro-studio" ]; then
    APP_DIR="/root/maestro-studio"
else
    APP_DIR="/var/www/maestro-studio"
fi

mkdir -p "$APP_DIR"
cd "$APP_DIR"

echo "=== [1/4] Estrazione del codice sorgente aggiornato ==="
cat << 'ARCHIVE_EOF' | base64 -d | tar -xzf -

ARCHIVE_EOF
echo "OK: File sorgenti estratti con successo."

echo "=== [2/4] Configurazione Git e Push su GitHub ==="
if command -v git &> /dev/null; then
    if [ ! -d ".git" ]; then
        git init
        git branch -M main 2>/dev/null || true
    fi
    git config user.name "msarti81-design"
    git config user.email "msarti81@gmail.com"

    if ! git remote get-url origin >/dev/null 2>&1; then
        git remote add origin https://github.com/msarti81-design/maestro-studio.git
    fi

    git add -A .
    COMMIT_MSG="Fix: AudioEngine direct path pristine piano sound ($(date '+%Y-%m-%d %H:%M:%S'))"
    git commit -m "$COMMIT_MSG" || echo "Nessuna modifica da committare."

    echo "Esecuzione push dei sorgenti aggiornati su GitHub (branch main)..."
    if git push -u origin main || git push origin main || git push -u origin master; then
        echo "----------------------------------------------------------"
        echo " ✓ SORGENTI AGGIORNATI SU GITHUB CON SUCCESSO!"
        echo " ✓ LA GITHUB ACTION E PARTITA PER COMPILARE IL NUOVO APK!"
        echo "----------------------------------------------------------"
    else
        echo "⚠️ Nota: Se viene richiesto un token di accesso personale GitHub (PAT),"
        echo "puoi impostarlo con: git remote set-url origin https://<TUO_TOKEN>@github.com/msarti81-design/maestro-studio.git"
    fi
fi

echo "=== [3/4] Aggiornamento servizio WebApp (Porta 5000) ==="
if command -v pm2 &> /dev/null; then
    pm2 delete maestro-studio 2>/dev/null || true
    PORT=5000 pm2 start server.js --name "maestro-studio" --cwd "$APP_DIR"
    pm2 save 2>/dev/null || true
    echo "OK: WebApp avviata su porta 5000."
fi

echo "=========================================================="
echo "  TUTTO FATTO!"
echo "  I sorgenti aggiornati sono su GitHub e l'APK verra"
echo "  ricompilato automaticamente con l'audio perfetto!"
echo "=========================================================="
